{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "IAM role with overly permissive managed policy",
      "resource": "aws_iam_role.pass1",
      "severity": "MEDIUM",
      "explanation": "The IAM role is attached to the managed policy 'AmazonS3ReadOnlyAccess', which grants read access to all S3 buckets in the account. This could lead to unintended data exposure if the role is compromised or misused. It is recommended to use a custom policy with least privilege access tailored to specific S3 buckets."
    }
  ],
  "patched_code": "resource "aws_iam_role" "pass1" {
  name                = "pass1"
  assume_role_policy  = data.aws_iam_policy_document.instance_assume_role_policy.json
  managed_policy_arns = []

  inline_policy {
    name   = "s3_read_access"
    policy = <<EOT
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "s3:GetObject",
      "Resource": "arn:aws:s3:::specific-bucket-name/*"
    }
  ]
}
EOT
  }
}
",
  "fix_summary": "Replaced the overly permissive managed policy 'AmazonS3ReadOnlyAccess' with a custom inline policy granting least privilege access to a specific S3 bucket."
}
